"""연결된 completion의 일반 Result 표현과 반복·변조·별칭 거절."""
import copy,hashlib,json,os,pathlib,subprocess,sys
c=pathlib.Path(sys.argv[1]);sdk=os.environ['CONFECTORY_DOTNET'];tool=c/'targets/element-authoring/bin/Release/net10.0/Confectory.ElementAuthoring.dll';ns='Owned.Sync';units={}
def m(op,ok=True,**req):
 r=subprocess.run([sdk,str(tool)],input=json.dumps(dict(operation=op,**req)),text=True,capture_output=True,check=True);v=json.loads(r.stdout);assert v['ok']==ok,v;return v.get('result',v)
def unit(id,kind,path,text):units[id]=dict(kind=kind,path=path,original=text,draft=text,baseline=hashlib.sha256(text.encode()).hexdigest(),revision=0)
fn=ns+'::Flow';impl=fn+'Body';gid=impl+'/body:common';a=m('blueprintPrepareFeature',id=fn,text='function '+fn+' (int value,out int total) -> void {}',implementation=impl,graphPath='Flow.graph.json',nodePath='Flow.node.json');g=a['graph'];g['profile']='sync-acyclic-switch-v1';node=g['nodes'][0];node['control']='switch';node['executionEnum']={'primary':'next','members':[{'id':'next','name':'None','value':0},{'id':'positive','name':'Positive','value':1},{'id':'negative','name':'Negative','value':2}]};g['nodes'].append(dict(id='done',kind='code',control='next',intent='completion region',signature=dict(args=[],return_='void'),arguments={},implementation='Done.node.json',branchOwner=node['id']));g['nodes'][-1]['signature']={'args':[],'return':'void'};g['edges'].append({'from':'done','port':'next','to':'return:'+node['id']})
defs=m('featureBlueprintNodes',featureSource=a['function'],graph=g);body='// 원본 😀\r\ntotal=value*2;return Result.Positive;\r\n';records={node['id']:dict(schema=1,node=node['id'],definitionHash=next(n['definitionHash']for n in defs['nodes']if n['id']==node['id']),source=body), 'done':dict(schema=1,node='done',definitionHash=next(n['definitionHash']for n in defs['nodes']if n['id']=='done'),source='global::System.Console.WriteLine("completed");')}
unit(fn,'function','Flow.celem',a['function']);unit(impl,'implementation','FlowBody.celem',a['implementation']);unit(gid,'blueprint','Flow.graph.json',json.dumps(g))
for key,rec in records.items():unit(gid+'/node:'+key,'blueprint-node','Flow.node.json' if key==node['id'] else 'Done.node.json',json.dumps(rec,ensure_ascii=False))
def transition(current,flag):
 v=m('blueprintAsyncTransition',namespace=ns,id=gid,units=current,plan=dict(enabled=True,nodes=[dict(node=node['id'],enabled=flag)]));u=copy.deepcopy(current);u.update(v['units']);return u
current=transition(units,True);g=json.loads(current[gid]['draft']);g['edges'].append({'from':node['id'],'port':'completion','to':'done'});current[gid]['draft']=json.dumps(g);prior=copy.deepcopy(current);u=transition(current,False);g=json.loads(u[gid]['draft']);demoted=next(n for n in g['nodes']if n['id']==node['id']);marker=demoted['completionBranch'];assert g['edges']==json.loads(current[gid]['draft'])['edges'];assert 'async'not in demoted;assert marker['label']=='완료 시';assert any(n['id']==marker['id']for n in demoted['executionEnum']['members']);assert [r for r in demoted['executionEnum']['members']if r['id']!=marker['id']]==node['executionEnum']['members'];assert json.loads(u[gid+'/node:'+node['id']]['draft'])['source']==body;assert m('blueprintAsyncGuards',namespace=ns,units=u)['valid'];print('PASS demotion retains exact wires, original Result members/out/C# and an ordinary labeled completion result',flush=True)
def describe(u):return m('featureBlueprintDescribe',featureSource=u[fn]['draft'],graph=json.loads(u[gid]['draft']),implementations={k:json.loads(u[gid+'/node:'+k]['draft'])for k in records})
d=describe(u);assert d['state']!='invalid',d
again=transition(u,True);off=transition(again,False);assert json.loads(off[gid]['draft'])==g;print('PASS async/sync repetition preserves marker identity/value and unchanged connections',flush=True)
bad=copy.deepcopy(u);v=json.loads(bad[gid]['draft']);next(n for n in v['nodes']if n['id']==node['id'])['completionBranch']['value']+=50;bad[gid]['draft']=json.dumps(v);m('blueprintAsyncGuards',False,namespace=ns,units=bad);print('PASS altered ordinary member receipt is rejected',flush=True)
bad=copy.deepcopy(u);v=json.loads(bad[gid]['draft']);v['edges'].append({'from':node['id'],'port':'case:'+marker['id'],'to':'done'});bad[gid]['draft']=json.dumps(v);d=describe(bad);assert d['state']=='invalid' and d['diagnostics'][0]['code']=='GRAPH_COMPLETION_ALIAS',d;print('PASS conflicting physical/case alias is rejected without selecting a replacement route',flush=True)

bad=copy.deepcopy(u);m('blueprintAsyncTransition',False,namespace=ns,id=gid,units=bad,plan=dict(enabled=False,nodes=[]));assert bad==u;print('PASS unfinished public function completion adapter fails without changing the candidate',flush=True)
changed=copy.deepcopy(demoted);member=next(r for r in changed['executionEnum']['members']if r['id']==marker['id']);member['name']='@종료_줄';edited=m('blueprintCompletionEdit',node=changed,edges=g['edges'],label='종료 줄');assert edited['completionBranch']['id']==marker['id'] and edited['completionBranch']['value']==marker['value'] and edited['completionBranch']['label']=='종료 줄';print('PASS display/C# rename retains the logical completion identity and value',flush=True)
changed['executionEnum']['members']=[r for r in changed['executionEnum']['members']if r['id']!=marker['id']];m('blueprintCompletionEdit',False,node=changed,edges=g['edges']);print('PASS removal of a still connected completion is rejected',flush=True)

no_op=m('blueprintAsyncTransition',namespace=ns,id=gid,units=units,plan=dict(enabled=False,nodes=[dict(node=node['id'],enabled=False)]));assert json.loads(no_op['units'][gid]['draft'])['nodes']==json.loads(units[gid]['draft'])['nodes'];print('PASS explicit unchanged sync selection does not invent a completion result',flush=True)
